<mini_swe_agent_bash>
cat > /workspace/verify_columns.py << 'EOF'
import sys
import statistics

lines = [line.rstrip('\n') for line in sys.stdin]

# Find the line that starts with '|1|' (first data row)
data_start = 0
for i, line in enumerate(lines):
    if line.startswith('|1|'):
        data_start = i
        break

# Column indices
recdroid_idx = 22
yakusu_idx = 55

recdroid_vals = []
yakusu_vals = []

# Process all data rows
for line in lines[data_start:]:
    if not line.startswith('|'):
        continue
    cells = line.strip('|').split('|')
    if len(cells) > recdroid_idx:
        val = cells[recdroid_idx].strip()
        if val and val != 'N/A' and val != 'N/A ':
            try:
                recdroid_vals.append(float(val))
            except ValueError:
                pass
    if len(cells) > yakusu_idx:
        val = cells[yakusu_idx].strip()
        if val and val != 'N/A' and val != 'N/A ':
            try:
                yakusu_vals.append(float(val))
            except ValueError:
                pass

print(f"ReCDroid values (first 10): {recdroid_vals[:10]}")
print(f"Yakusu values (first 10): {yakusu_vals[:10]}")
print(f"Number of ReCDroid values: {len(recdroid_vals)}")
print(f"Number of Yakusu values: {len(yakusu_vals)}")
if recdroid_vals:
    print(f"ReCDroid avg: {sum(recdroid_vals)/len(recdroid_vals):.0f}, median: {statistics.median(recdroid_vals):.0f}")
if yakusu_vals:
    print(f"Yakusu avg: {sum(yakusu_vals)/len(yakusu_vals):.0f}, median: {statistics.median(yakusu_vals):.0f}")
EOF
</mini_swe_agent_bash>

